using System;
using System.Collections;
using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace bankingonaspdotnet.Domain;

/// <summary>
/// PaymentMethod enumerator class
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]

public enum PaymentMethod
{
    InternalTransfer = 1, ACH = 2, Wire = 3, SEPA = 4, SWIFT = 5, Card = 6, Cash = 7, Check = 8, MobileWallet = 9
}

/// <summary>
/// Extension of capabilities for the PaymentMethod enum
/// </summary>
public static class PaymentMethodExtensions
{
    //************************************************************************
    // static implementations
    //************************************************************************
    public static List<PaymentMethod> GetValues()
    {
        return Enum.GetValues<PaymentMethod>().ToList();
    }

    public static PaymentMethod GetDefaultValue()
    {
        return Enum.GetValues<PaymentMethod>().First();
    }

    public static PaymentMethod WhichOne(string name)
    {
        if (Enum.TryParse<PaymentMethod>(name, true, out var value))
        {
            return value;
        }

        return GetDefaultValue();
    }
}



